/* mpp-detail panel 9 A */ SELECT lpad(s.bucket_number::text,2,'0')||' 时' AS bucket,s.p50_ms AS "P50",s.p95_ms AS "P95"
FROM mpp_view_statistics('${norm}','${fp}','${identity}','${version}','hour') s WHERE s.timing_type='${timing}' AND s.included_count>0
ORDER BY s.bucket_date,s.bucket_number

/* mpp-detail panel 10 A */ SELECT to_char(s.bucket_date,'MM-DD') AS bucket,s.p50_ms AS "P50",s.p95_ms AS "P95"
FROM mpp_view_statistics('${norm}','${fp}','${identity}','${version}','day') s WHERE s.timing_type='${timing}' AND s.included_count>0
ORDER BY s.bucket_date,s.bucket_number

/* mpp-detail panel 12 A */ SELECT (ARRAY['周一','周二','周三','周四','周五','周六','周日'])[s.bucket_number] AS bucket,s.p50_ms AS "P50",s.p95_ms AS "P95"
FROM mpp_view_statistics('${norm}','${fp}','${identity}','${version}','weekday') s WHERE s.timing_type='${timing}' AND s.included_count>0
ORDER BY s.bucket_date,s.bucket_number

/* mpp-detail panel 13 A */ SELECT to_char(s.bucket_date,'MM-DD')||' 起' AS bucket,s.p50_ms AS "P50",s.p95_ms AS "P95"
FROM mpp_view_statistics('${norm}','${fp}','${identity}','${version}','week') s WHERE s.timing_type='${timing}' AND s.included_count>0
ORDER BY s.bucket_date,s.bucket_number
